using System;using System.IO;using System.Reflection;using System.Security.Cryptography;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Game.Runtime;
internal static class OwnerArtifactReuseControls {
 static int checks;static readonly JArray cases=new JArray();static readonly MethodInfo read=typeof(SourcePlacementDomain).GetMethod("ReadOwnerArtifact",BindingFlags.NonPublic|BindingFlags.Static);static bool Candidate=>read.GetParameters().Length==3;
 static string Sha(string p){using(var h=SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 static JObject Read(string p,string sha,JObject prior=null){try{return(JObject)read.Invoke(null,Candidate?new object[]{p,sha,prior}:new object[]{p,sha});}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;cases.Add(new JObject{["case"]=name,["status"]="Passed"});}
 static void Reject(Action action,Type expected,Func<Exception,bool> reason,string name){try{action();}catch(Exception error){if(error.GetType()!=expected||!reason(error))throw new Exception("Unexpected exception for "+name+": "+error.GetType().FullName+": "+error.Message,error);checks++;cases.Add(new JObject{["case"]=name,["status"]="Passed",["exception_type"]=error.GetType().FullName,["exception_message"]=error.Message});return;}throw new Exception("Expected original rejection: "+name);}
 static bool JsonLocation(Exception error){var e=(JsonReaderException)error;return e.LineNumber==1&&e.LinePosition>0&&e.Message.IndexOf("line 1",StringComparison.Ordinal)>=0;}
 static void Write(string path,JObject result){using(var f=new FileStream(path,FileMode.CreateNew,FileAccess.Write))using(var w=new StreamWriter(f))w.WriteLine(result.ToString(Formatting.Indented));}
 static int Main(string[] args){string output=null;try{if(args.Length!=2||(args[0]!="baseline"&&args[0]!="candidate"))throw new ArgumentException("Expected baseline|candidate and fresh result JSON path");output=Path.GetFullPath(args[1]);if(File.Exists(output)||!Directory.Exists(Path.GetDirectoryName(output)))throw new ArgumentException("Fresh result path in existing isolated output directory required");if(read==null||(read.GetParameters().Length!=2&&read.GetParameters().Length!=3)||Candidate!=(args[0]=="candidate"))throw new Exception("Unexpected owner helper/mode");string dir=Path.Combine(Path.GetDirectoryName(output),"owner-artifact-cases");if(Directory.Exists(dir))throw new ArgumentException("Fresh owned case directory required");Directory.CreateDirectory(dir);string a=Path.Combine(dir,"a.json"),b=Path.Combine(dir,"b.json");File.WriteAllText(a,"{\"value\":1,\"nested\":[true,false,3]}");string sha=Sha(a);var first=Read(a,sha);Check((int)first["value"]==1,"first strict parse");var second=Read(a,sha,first);Check(JToken.DeepEquals(first,second),"equal parsed content");Check(!Candidate||ReferenceEquals(first,second),"candidate local identity reuse");File.Copy(a,b);var distinct=Read(b,sha);Check(!ReferenceEquals(first,distinct)&&JToken.DeepEquals(first,distinct),"distinct path fresh parse fallback");Reject(()=>Read(a,new string('0',64),first),typeof(InvalidDataException),e=>e.Message=="Original owner capture changed","second SHA verification before reuse");File.WriteAllText(a,"{\"value\":2}");Reject(()=>Read(a,sha,first),typeof(InvalidDataException),e=>e.Message=="Original owner capture changed","file changed between reads");File.Delete(a);Reject(()=>Read(a,sha,first),typeof(NotSupportedException),e=>e.Message=="Bounded regular source geometry file required","file disappeared between reads");File.WriteAllText(a,"{bad");Reject(()=>Read(a,Sha(a)),typeof(JsonReaderException),JsonLocation,"malformed first parse");File.WriteAllText(a,"{\"value\":1,\"value\":2}");Reject(()=>Read(a,Sha(a)),typeof(JsonReaderException),e=>JsonLocation(e)&&e.Message.StartsWith("Property with the name 'value' already exists",StringComparison.Ordinal),"duplicate first parse");Write(output,new JObject{["result"]="Passed",["checks"]=checks,["candidate"]=Candidate,["world"]=false,["cases"]=cases,["scope"]="Private parser helper only; not full frame/mask/water/contract negatives or mission/native readiness"});Console.WriteLine("[OwnerArtifactReuseControls] result=Passed checks="+checks+" candidate="+Candidate+" world=False");return 0;}catch(Exception error){Console.Error.WriteLine(error);if(output!=null&&!File.Exists(output)){try{Write(output,new JObject{["result"]="Failed",["checks_reached"]=checks,["cases"]=cases,["exception"]=error.ToString(),["world"]=false});}catch(Exception){}}return 1;}}
}
